steps.text:
class VIOC_BASE_STYLE {
	title = "VIOC: Estilo de bases y estructuras (edificios, FOB, pueblos, fortificaciones)";
	values[] = {0,1};
	texts[] = {"Original","Nuevo (estilo Reforger)"};
	default = 1;
};

//--- VIOC base_structures_style (agregado por tools/vio_build.py; copia configurada, no es del autor de la mision).
//--- Parametro de lobby VIOC_BASE_STYLE: 0 = edificios originales, 1 = estilo nuevo (por defecto; tambien en el editor).
//--- Solo cambia el edificio TERMINADO de cada estructura y su ruina. La obra en construccion, precios, tiempos,
//--- puntos de compra y toda la logica siguen igual. Oeste = OTAN/EE.UU.; Este = sovietico/ruso (Livonia y CUP).
//--- Cada clase se prueba con isClass: si no existe (mod no cargado) se usa la alternativa y, si no, la original.
//--- Ninguna clase se repite dentro de un bando (claves CTI_<bando>_<clase>). La vida efectiva no cambia:
//--- DMG_Reduce se escala por armadura del edificio original / armadura del nuevo.
//--- Variante 'servicio gratis': un tipo solo cambia de edificio si el nuevo ofrece los mismos servicios del motor
//--- (rearmar, repostar, reparar, curar). Con CUP el deposito de municion original (RU_WarfareBVehicleServicePoint)
//--- rearma, repara y reposta gratis a 15 m, asi que se queda como estaba.
//--- El HQ del Oeste es la tienda OTAN abierta (se entra; la cerrada no tiene puertas que se abran).
if ((missionNamespace getVariable ["VIOC_BASE_STYLE", 1]) > 0) then {
	private _vioc_map = if (_side == east) then {[
		[CTI_HQ_DEPLOYED, [["Land_GuardHouse_02_F", "Land_GuardHouse_02_ruins_F"]]],
		[CTI_BARRACKS, [["Land_Barracks_02_F", "Land_Barracks_02_ruins_F"]]],
		[CTI_LIGHT, [["Land_GarageRow_01_small_F", "Land_GarageRow_01_small_ruins_F"]]],
		[CTI_CONTROLCENTER, [["Land_MobileRadar_01_radar_F", "Land_MobileRadar_01_radar_ruins_F"]]],
		[CTI_HEAVY, [["Land_GarageRow_01_large_F", "Land_GarageRow_01_large_ruins_F"]]],
		[CTI_AIR, [["Land_ControlTower_02_F", "Land_ControlTower_02_ruins_F"]]],
		[CTI_AMMO, [["Land_Ammostore2", ""], ["Land_Workshop_01_grey_F", "Land_Workshop_01_ruins_F"]]],
		[CTI_REPAIR, [["Land_Repair_center", "Land_Repair_center_ruins"], ["Land_Workshop_03_F", "Land_Workshop_03_ruins_F"]]],
		[CTI_NAVAL, [["Land_Workshop_04_F", "Land_Workshop_04_ruins_F"]]]
	]} else {[
		[CTI_HQ_DEPLOYED, [["Land_MedicalTent_01_NATO_generic_open_F", "Land_MedicalTent_01_NATO_generic_open_F"]]],
		[CTI_BARRACKS, [["Land_Cargo_HQ_V1_F", "Land_Cargo_HQ_V1_ruins_F"]]],
		[CTI_LIGHT, [["CamoNet_BLUFOR_big_F", ""]]],
		[CTI_CONTROLCENTER, [["Land_Radar_Small_F", "Land_Radar_Small_ruins_F"]]],
		[CTI_HEAVY, [["Land_Cargo_HQ_V3_F", "Land_Cargo_HQ_V3_ruins_F"]]],
		[CTI_AIR, [["Land_Cargo_Tower_V1_F", "Land_Cargo_Tower_V1_ruins_F"]]],
		[CTI_AMMO, [["Land_Cargo_House_V1_F", "Land_Cargo_House_V1_ruins_F"]]],
		[CTI_REPAIR, [["Land_Shed_06_F", "Land_Shed_06_ruins_F"]]],
		[CTI_NAVAL, [["Land_Cargo_House_V4_F", "Land_Cargo_House_V4_ruins_F"]]]
	]};
	private _vioc_armor = {getNumber (configFile >> "CfgVehicles" >> _this >> "armor")};
	private _vioc_caps = {private _vioc_cfg = configFile >> "CfgVehicles" >> _this; [getNumber (_vioc_cfg >> "transportAmmo") > 0, getNumber (_vioc_cfg >> "transportFuel") > 0, getNumber (_vioc_cfg >> "transportRepair") > 0, getNumber (_vioc_cfg >> "attendant") > 0]};
	//--- 1) primera clase que exista para cada tipo presente en esta mision
	private _vioc_plan = [];
	{
		private _vioc_type = _x select 0;
		private _vioc_cands = _x select 1;
		private _vioc_idx = -1;
		{ if ((_x select 0) == _vioc_type) exitWith {_vioc_idx = _forEachIndex} } forEach _headers;
		if (_vioc_idx > -1) then {
			private _vioc_pick = [];
			private _vioc_need = ((_classes select _vioc_idx) select 0) call _vioc_caps;
			{ if (isClass (configFile >> "CfgVehicles" >> (_x select 0)) && {(({_x} count _vioc_need) == 0) || {((_x select 0) call _vioc_caps) isEqualTo _vioc_need}}) exitWith {_vioc_pick = _x} } forEach _vioc_cands;
			if (count _vioc_pick > 0) then {_vioc_plan pushBack [_vioc_idx, _vioc_pick]};
		};
	} forEach _vioc_map;
	//--- 2) si una clase nueva repetiria otra del mismo bando, ese tipo conserva la suya
	private _vioc_names = _classes apply {toLower (_x select 0)};
	{ _vioc_names set [_x select 0, toLower ((_x select 1) select 0)] } forEach _vioc_plan;
	private _vioc_ok = [];
	{
		private _vioc_i = _x select 0;
		private _vioc_n = _vioc_names select _vioc_i;
		if (({_x == _vioc_n} count _vioc_names) == 1) then {
			_vioc_ok pushBack _x;
		} else {
			_vioc_names set [_vioc_i, toLower ((_classes select _vioc_i) select 0)];
		};
	} forEach _vioc_plan;
	//--- si aun quedara alguna clase repetida, este bando se queda con los edificios originales
	if ((count _vioc_names) != (count (_vioc_names arrayIntersect _vioc_names))) then {_vioc_ok = []};
	//--- 3) aplicar
	{
		private _vioc_i = _x select 0;
		private _vioc_new = (_x select 1) select 0;
		private _vioc_ruin = (_x select 1) select 1;
		private _vioc_cls = _classes select _vioc_i;
		private _vioc_old = _vioc_cls select 0;
		private _vioc_extra = if (count _vioc_cls > 2) then {+(_vioc_cls select 2)} else {[]};
		private _vioc_hasRuin = (_vioc_ruin != "") && {isClass (configFile >> "CfgVehicles" >> _vioc_ruin)};
		if (((_headers select _vioc_i) select 0) == CTI_HQ_DEPLOYED) then {
			//--- HQ: el 2o elemento son los restos que deja al destruirse (se crean con setDamage 1)
			_classes set [_vioc_i, [_vioc_new, if (_vioc_hasRuin) then {_vioc_ruin} else {_vioc_new}]];
		} else {
			//--- el 2o elemento (obra en construccion) no cambia; la ruina del motor va en el 3o para que se borre
			if (_vioc_hasRuin) then {_vioc_extra pushBackUnique _vioc_ruin};
			_classes set [_vioc_i, if (count _vioc_extra > 0) then {[_vioc_new, _vioc_cls select 1, _vioc_extra]} else {[_vioc_new, _vioc_cls select 1]}];
		};
		//--- misma vida efectiva que antes: DMG_Reduce x (armadura original / armadura nueva)
		private _vioc_ao = _vioc_old call _vioc_armor;
		private _vioc_an = _vioc_new call _vioc_armor;
		private _vioc_ratio = if (_vioc_ao > 0 && {_vioc_an > 0}) then {_vioc_ao / _vioc_an} else {1};
		{ if ((_x select 0) == "DMG_Reduce") then {_x set [1, ((_x select 1) * _vioc_ratio) max 0.05]} } forEach (_specials select _vioc_i);
	} forEach _vioc_ok;
};

//--- VIOC base_structures_style: el FOB es una tienda medica del bando (Oeste MTP, Este verde oliva) que cura como el
//--- hospital de campana original de CUP (attendant). Las tiendas medicas que curan son las 'cerradas': al construir
//--- el FOB se ocultan sus puertas (Server_BuildDefense.sqf) para poder entrar (el equipo pide estar a 4 m del centro).
//--- Si la clase no existe, ya es una estructura del bando o no cura cuando la original si, queda la original.
//--- Sin ruina que limpiar. Los FOB guardados con un estilo no vuelven con el otro.
if ((missionNamespace getVariable ["VIOC_BASE_STYLE", 1]) > 0 && {count _headers > 0} && {((_headers select 0) select 0) == "FOB"}) then {
	private _vioc_fob = if (_side == east) then {"Land_MedicalTent_01_tropic_closed_F"} else {"Land_MedicalTent_01_MTP_closed_F"};
	private _vioc_heal = {getNumber (configFile >> "CfgVehicles" >> _this >> "attendant")};
	if (isClass (configFile >> "CfgVehicles" >> _vioc_fob) && {isNil {missionNamespace getVariable format ["CTI_%1_%2", _side, _vioc_fob]}} && {((_classes select 0) call _vioc_heal) <= (_vioc_fob call _vioc_heal)}) then {
		_classes set [0, _vioc_fob];
		{ if ((_x select 0) == "RuinOnDestroyed") then {_x set [1, ""]} } forEach ((_headers select 0) select 1);
	};
};

//--- VIOC base_structures_style: estructuras nuevas en el menu de construccion del comandante (sacos terreros,
//--- barricadas, bunker, alambre, torres, redes de camuflaje, tienda). Solo con VIOC_BASE_STYLE = 1. Categorias nuevas
//--- "Fortification" y "Camo" (la IA comandante no las compra). Mapas boscosos: version verde. Cada clase se prueba con
//--- isClass; si ya estaba en el menu (o es una estructura del bando) Set_Defenses se queda con la primera definicion.
//--- 7a columna opcional: ruina del motor que se borra al destruirse (garita).
if ((missionNamespace getVariable ["VIOC_BASE_STYLE", 1]) > 0) then {
	private _vioc_green = (toLower worldName) in ["chernarus", "chernarus_summer", "chernarus_winter", "cup_chernarus_a3", "enoch", "tanoa", "sara", "saralite", "sara_dbe1", "woodland_acr", "bootcamp_acr", "provinggrounds_pmc", "porto", "intro", "eden", "cain", "abel", "noe", "gm_weferlingen_summer", "gm_weferlingen_winter", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra", "stozec"];
	private _vioc_price = {[CTI_ECONOMY_PRIZE_EQUIPMENT, 0, false, _this] call CTI_CO_FNC_GetCalculatedUnitsPrize};
	{
		_x params ["_vioc_label", "_vioc_g", "_vioc_o", "_vioc_mult", "_vioc_cat", "_vioc_align", ["_vioc_ruin", ""]];
		private _vioc_cls = if (_vioc_green) then {_vioc_g} else {_vioc_o};
		if (isClass (configFile >> "CfgVehicles" >> _vioc_cls)) then {
			private _vioc_spec = [];
			if (_vioc_align > 0) then {_vioc_spec pushBack ["CanAutoAlign", _vioc_align, 0]};
			if (_vioc_ruin != "" && {isClass (configFile >> "CfgVehicles" >> _vioc_ruin)}) then {_vioc_spec pushBack ["RuinOnDestroyed", _vioc_ruin]};
			_headers pushBack (if (count _vioc_spec > 0) then {[_vioc_label, _vioc_spec]} else {_vioc_label});
			_classes pushBack _vioc_cls;
			_prices pushBack (_vioc_mult call _vioc_price);
			_placements pushBack [0, 7];
			_categories pushBack _vioc_cat;
			_tiers pushBack 0;
		};
	} forEach [
		["Sandbag Wall (Long)", "Land_BagFence_01_long_green_F", "Land_BagFence_Long_F", 1, "Fortification", 3],
		["Sandbag Wall (Short)", "Land_BagFence_01_short_green_F", "Land_BagFence_Short_F", 0.75, "Fortification", 1.9],
		["Sandbag Wall (Round)", "Land_BagFence_01_round_green_F", "Land_BagFence_Round_F", 1, "Fortification", 0],
		["Sandbag Wall (Corner)", "Land_BagFence_01_corner_green_F", "Land_BagFence_Corner_F", 0.5, "Fortification", 0],
		["Sandbag Wall (End)", "Land_BagFence_01_end_green_F", "Land_BagFence_End_F", 0.5, "Fortification", 0],
		["Sandbag Barricade (Low)", "Land_SandbagBarricade_01_half_F", "Land_SandbagBarricade_01_half_F", 1.5, "Fortification", 2.6],
		["Sandbag Barricade (Tall)", "Land_SandbagBarricade_01_F", "Land_SandbagBarricade_01_F", 2, "Fortification", 2.6],
		["Sandbag Barricade (Loophole)", "Land_SandbagBarricade_01_hole_F", "Land_SandbagBarricade_01_hole_F", 2, "Fortification", 2.6],
		["Sandbag Bunker (Small)", "Land_BagBunker_01_small_green_F", "Land_BagBunker_Small_F", 3, "Fortification", 0],
		["Earth Rampart", "Land_fort_rampart", "Land_fort_rampart_EP1", 3, "Fortification", 0],
		["Razor Wire", "Land_Razorwire_F", "Land_Razorwire_F", 1, "Fortification", 8.2],
		["Dragon's Teeth", "Land_DragonsTeeth_01_4x2_old_F", "Land_DragonsTeeth_01_4x2_old_F", 2, "Fortification", 0],
		["Guard Box", "Land_GuardBox_01_brown_F", "Land_GuardBox_01_brown_F", 3, "Fortification", 0, "Land_GuardBox_01_brown_ruins_F"],
		["Watchtower (Concrete)", "Land_GuardTower_02_F", "Land_GuardTower_02_F", 4, "Fortification", 0],
		["Watchtower (Wooden, Big)", "Land_GuardTower_01_F", "Land_GuardTower_01_F", 6, "Fortification", 0],
		["Camo Net", "CamoNet_wdl_F", "CamoNet_INDP_F", 2, "Camo", 0],
		["Camo Net (Open)", "CamoNet_wdl_open_F", "CamoNet_INDP_open_F", 2, "Camo", 0],
		["Camo Net (Vehicle)", "CamoNet_wdl_big_F", "CamoNet_INDP_big_F", 3, "Camo", 0],
		["Field Tent (Open)", "Land_MedicalTent_01_wdl_generic_open_F", "Land_MedicalTent_01_aaf_generic_open_F", 2, "Camo", 0]
	];
};

//--- VIOC base_structures_style (agregado por tools/vio_build.py; copia configurada, no es del autor de la mision).
//--- Modelos de los pueblos con el estilo nuevo (parametro de lobby VIOC_BASE_STYLE, por defecto 1). Son los mismos
//--- para los dos bandos porque los pueblos cambian de dueno. Mapas boscosos: sacos terreros verdes; resto: arena.
//--- Deposito: misma planta de 11 x 11 m que el original, asi que las 4 banderas quedan donde estaban.
//--- Campamento: torre de sacos de 6.4 x 9.8 m (en vez de Fortress2 de 8.9 x 8 m), bandera fuera de los muros.
//--- Solo se usa una clase si existe y no es una defensa construible de ningun bando (si lo fuera, la herramienta de
//--- quitar defensas podria borrar depositos o campamentos: pasa en la mision vanilla con Land_BagBunker_Tower_F).
if ((missionNamespace getVariable ["VIOC_BASE_STYLE", 1]) > 0) then {
	private _vioc_green = (toLower worldName) in ["chernarus", "chernarus_summer", "chernarus_winter", "cup_chernarus_a3", "enoch", "tanoa", "sara", "saralite", "sara_dbe1", "woodland_acr", "bootcamp_acr", "provinggrounds_pmc", "porto", "intro", "eden", "cain", "abel", "noe", "gm_weferlingen_summer", "gm_weferlingen_winter", "cam_lao_nam", "vn_khe_sanh", "vn_the_bra", "stozec"];
	private _vioc_depot = if (_vioc_green) then {"Land_BagBunker_01_large_green_F"} else {"Land_BagBunker_Large_F"};
	private _vioc_camp = if (_vioc_green) then {"Land_HBarrier_01_tower_green_F"} else {"Land_BagBunker_Tower_F"};
	private _vioc_free = {
		private _vioc_c = _this;
		isClass (configFile >> "CfgVehicles" >> _vioc_c) && {({!isNil {missionNamespace getVariable format ["CTI_%1_%2", _x, _vioc_c]}} count [west, east]) == 0}
	};
	if (_vioc_depot call _vioc_free) then {
		missionNamespace setVariable ["CTI_CO_DEPOT", _vioc_depot];
	};
	if (_vioc_camp call _vioc_free) then {
		missionNamespace setVariable ["CTI_CO_CAMP", _vioc_camp];
		missionNamespace setVariable ["CTI_CO_CAMP_FLAG_POS", [-5,5]];
		missionNamespace setVariable ["CTI_CO_CAMP_RDIR", 0];
	};
};
